"use client";

import React, { useState, useEffect, useRef, useCallback } from "react";
import { usePathname } from "next/navigation";
import { motion, AnimatePresence } from "framer-motion";
import { Map, Zap, CheckCircle2, Train, ChevronRight, X, Sparkles, TrainFront, Mic } from "lucide-react";
import { useLanguage } from "./LanguageContext";

// Fallback Error Boundary just for this component
class OnboardingBoundary extends React.Component<{children: React.ReactNode}, {hasError: boolean}> {
  constructor(props: {children: React.ReactNode}) {
    super(props);
    this.state = { hasError: false };
  }
  static getDerivedStateFromError() { return { hasError: true }; }
  componentDidCatch(error: any, errorInfo: any) { console.error("Onboarding failed:", error); }
  render() { if (this.state.hasError) return null; return this.props.children; }
}

function OnboardingOverlayInner() {
  const [mounted, setMounted] = useState(false);
  const [isVisible, setIsVisible] = useState(false);
  const [currentSlide, setCurrentSlide] = useState(0);
  const modalRef = useRef<HTMLDivElement>(null);
  const pathname = usePathname();
  const { isHindi } = useLanguage();

  const slides = [
    {
      id: "welcome",
      badge: isHindi ? "स्मार्ट रेलवे असिस्टेंट" : "Smart Railway Assistant",
      title: "Trayago",
      isBrand: true,
      description: isHindi
        ? "भारतीय रेलवे का संपूर्ण AI साथी। स्प्लिट जर्नी, रियल-टाइम GPS ट्रैकिंग, PNR प्रेडिक्शन और वॉइस गाइडेंस।"
        : "Your AI-powered Indian Railway travel companion. Split journeys, real-time GPS tracking, PNR predictions & voice guidance.",
      highlights: isHindi
        ? ["⚡ AI स्प्लिट रूट्स", "📡 लाइव GPS ट्रैकिंग", "🎙️ प्रिया और रोहन वॉइस"]
        : ["⚡ AI Split Routes", "📡 Live GPS Tracking", "🎙️ Priya & Rohan Voice"],
      color: "bg-blue-500/10 border-blue-500/20"
    },
    {
      id: "search",
      badge: isHindi ? "सर्च इंजन" : "Search Engine",
      title: isHindi ? "इंटेलिजेंट ट्रेन सर्च" : "Intelligent Train Search",
      description: isHindi
        ? "सभी भारतीय रेलवे रूटों पर डायरेक्ट ट्रेनें और रियल-टाइम सीट उपलब्धता तुरंत खोजें।"
        : "Find direct routes and real-time seat availability across the entire Indian Railways network.",
      icon: <Map className="w-14 h-14 text-emerald-500" />,
      color: "bg-emerald-500/10 border-emerald-500/20"
    },
    {
      id: "pnr",
      badge: isHindi ? "कन्फर्मेशन AI" : "Confirmation AI",
      title: isHindi ? "स्मार्ट PNR प्रेडिक्शन" : "Smart PNR Prediction",
      description: isHindi
        ? "ऐतिहासिक डेटा और मशीन लर्निंग से अपने वेटलिस्ट टिकट के कन्फर्म होने की सटीक संभावना जानें।"
        : "Know your waitlist confirmation chances powered by historical chart preparation patterns.",
      icon: <CheckCircle2 className="w-14 h-14 text-indigo-500" />,
      color: "bg-indigo-500/10 border-indigo-500/20"
    },
    {
      id: "live",
      badge: isHindi ? "लाइव ट्रैकिंग" : "Live Tracking",
      title: isHindi ? "रियल-टाइम GPS स्टेटस" : "Real-Time GPS Tracking",
      description: isHindi
        ? "ट्रेन की सटीक गति (किमी/घंटा), प्लेटफॉर्म नंबर और आगामी स्टेशन के समय को सीधे ट्रैक करें।"
        : "Track train running speed in km/h, platform numbers, station delays, and audio updates.",
      icon: <Train className="w-14 h-14 text-amber-500" />,
      color: "bg-amber-500/10 border-amber-500/20"
    },
    {
      id: "split",
      badge: isHindi ? "स्प्लिट टिकटिंग" : "Split Ticketing",
      title: isHindi ? "AI स्प्लिट जर्नी इंजन" : "AI Split Journey Engine",
      description: isHindi
        ? "जब डायरेक्ट ट्रेनें फुल हों, तो ट्रेयागो कानूनी रूप से 2 कनेक्टिंग टिकट जोड़कर कन्फर्म सीट दिलाता है।"
        : "When direct trains are full, Trayago discovers verified multi-ticket combinations to get you home.",
      icon: <Zap className="w-14 h-14 text-rose-500" />,
      color: "bg-rose-500/10 border-rose-500/20"
    },
    {
      id: "voice",
      badge: isHindi ? "वॉइस इंजन" : "Voice Assistant",
      title: isHindi ? "द्विभाषी वॉइस असिस्टेंट" : "Bilingual Voice Assistant",
      description: isHindi
        ? "प्रिया और रोहन की आवाज में लाइव ट्रेन स्पीड, वेटलिस्ट एडवाइस और हैंड्स-फ्री घोषणाएं सुनें।"
        : "Hear train speed, live running alerts, and waitlist advice spoken clearly by Priya & Rohan.",
      icon: <Mic className="w-14 h-14 text-sky-500" />,
      color: "bg-sky-500/10 border-sky-500/20"
    },
    {
      id: "premium",
      badge: isHindi ? "प्रीमियम" : "Trayago Premium",
      title: isHindi ? "अल्ट्रा-फास्ट एक्सपीरियंस" : "Priority & Ad-Free",
      description: isHindi
        ? "फास्टेस्ट रूट सर्च, बैकग्राउंड अलर्ट्स और बिना किसी रुकावट के बेहतरीन यात्रा अनुभव पाएं।"
        : "Unlock priority search, instant notifications, and ad-free tracking for the ultimate journey.",
      icon: <Sparkles className="w-14 h-14 text-purple-500" />,
      color: "bg-purple-500/10 border-purple-500/20"
    }
  ];

  const checkStatus = useCallback(() => {
    try {
      const hasSeen = localStorage.getItem("has_seen_onboarding");
      if (!hasSeen && pathname === "/") {
        setIsVisible(true);
      }
    } catch (e) {
      // Ignore localStorage errors and let app run normally
    }
  }, [pathname]);

  useEffect(() => {
    setMounted(true);
    checkStatus();

    const handleOpen = () => {
      setCurrentSlide(0);
      setIsVisible(true);
    };

    window.addEventListener('OPEN_ONBOARDING', handleOpen);
    return () => {
      window.removeEventListener('OPEN_ONBOARDING', handleOpen);
    };
  }, [checkStatus]);

  const closeAndComplete = useCallback(() => {
    setIsVisible(false);
    try {
      localStorage.setItem("has_seen_onboarding", "true");
    } catch (e) {}
  }, []);

  // Handle ESC and Focus trap
  useEffect(() => {
    if (!isVisible) return;
    const handleKeyDown = (e: KeyboardEvent) => {
      if (e.key === "Escape") closeAndComplete();
    };
    document.addEventListener("keydown", handleKeyDown);
    return () => document.removeEventListener("keydown", handleKeyDown);
  }, [isVisible, closeAndComplete]);

  if (!mounted || !isVisible) return null;

  const slide = slides[currentSlide];

  return (
    <div
      className="fixed inset-0 z-[9999] flex items-center justify-center p-4 bg-black/75 backdrop-blur-md"
      role="dialog"
      aria-modal="true"
      aria-label="App Onboarding"
      ref={modalRef}
    >
      <AnimatePresence mode="wait">
        <motion.div
          key={currentSlide}
          initial={{ opacity: 0, y: 15, scale: 0.96 }}
          animate={{ opacity: 1, y: 0, scale: 1 }}
          exit={{ opacity: 0, y: -15, scale: 0.96 }}
          transition={{ duration: 0.25, ease: "easeOut" }}
          className="bg-card border border-subtle/80 rounded-3xl w-full max-w-md overflow-hidden shadow-2xl flex flex-col relative"
        >
          {/* Subtle Ambient Radial Glow */}
          <div className="absolute -top-20 -right-20 w-48 h-48 bg-blue-500/10 rounded-full blur-3xl pointer-events-none" />

          {/* Header */}
          <div className="flex justify-between items-center p-4.5 border-b border-subtle/60 relative z-10">
            <div className="flex items-center space-x-1.5">
              {slides.map((_, i) => (
                <div
                  key={i}
                  className={`h-1.5 rounded-full transition-all duration-300 ${i === currentSlide ? 'w-6 bg-primary' : i < currentSlide ? 'w-2 bg-primary/50' : 'w-2 bg-input'}`}
                />
              ))}
            </div>
            <button
              onClick={closeAndComplete}
              className="p-1.5 text-muted hover:text-main hover:bg-input rounded-full transition-colors cursor-pointer"
              aria-label="Close Tour"
            >
              <X className="w-5 h-5" />
            </button>
          </div>

          {/* Content */}
          <div className="p-7 flex flex-col items-center text-center relative z-10">
            {slide.isBrand ? (
              /* Brand Slide with Official Emblem */
              <div className="flex flex-col items-center">
                {/* Official Squircle Brand Emblem */}
                <div className="relative w-24 h-24 rounded-3xl bg-gradient-to-br from-blue-500 via-blue-600 to-indigo-700 p-0.5 shadow-xl shadow-blue-500/30 flex items-center justify-center mb-4">
                  <div className="w-full h-full rounded-[22px] bg-gradient-to-br from-blue-600 to-blue-800 flex flex-col items-center justify-center border border-white/20">
                    <TrainFront className="w-11 h-11 text-white drop-shadow-md" />
                    {/* Glowing Twin Headlights */}
                    <div className="flex gap-4 mt-1">
                      <span className="w-1.5 h-1.5 rounded-full bg-cyan-300 shadow-[0_0_8px_#38bdf8]" />
                      <span className="w-1.5 h-1.5 rounded-full bg-cyan-300 shadow-[0_0_8px_#38bdf8]" />
                    </div>
                  </div>
                </div>

                {/* Subtitle Pill Badge */}
                <div className="inline-flex items-center gap-1.5 px-3 py-1 rounded-full bg-blue-500/10 border border-blue-500/30 text-[11px] font-black uppercase tracking-wider text-blue-600 dark:text-blue-400 mb-2">
                  <span className="w-2 h-2 rounded-full bg-emerald-500 animate-pulse" />
                  {slide.badge}
                </div>

                {/* Brand Name Typography */}
                <h2 className="text-3xl font-display font-black tracking-tighter uppercase text-main">
                  Tray<span className="text-blue-600 dark:text-blue-400">ago</span>
                </h2>

                <p className="text-xs sm:text-sm text-secondary font-medium max-w-sm leading-relaxed mt-2.5">
                  {slide.description}
                </p>

                {/* Feature Chips */}
                {slide.highlights && (
                  <div className="mt-4 flex flex-wrap justify-center gap-1.5">
                    {slide.highlights.map((h, idx) => (
                      <span
                        key={idx}
                        className="px-2.5 py-1 rounded-lg bg-card/90 border border-subtle text-[10.5px] font-bold text-muted shadow-xs"
                      >
                        {h}
                      </span>
                    ))}
                  </div>
                )}
              </div>
            ) : (
              /* Feature Slides */
              <div className="flex flex-col items-center space-y-4">
                <div className={`w-28 h-28 rounded-3xl flex items-center justify-center border-2 shadow-lg ${slide.color}`}>
                  {slide.icon}
                </div>

                <div className="inline-flex items-center gap-1.5 px-3 py-0.5 rounded-full bg-primary/10 border border-primary/20 text-[10px] font-black uppercase tracking-wider text-primary">
                  {slide.badge}
                </div>

                <div className="space-y-1.5">
                  <h2 className="text-2xl font-black text-main">{slide.title}</h2>
                  <p className="text-xs sm:text-sm text-secondary max-w-sm leading-relaxed">{slide.description}</p>
                </div>
              </div>
            )}
          </div>

          {/* Footer */}
          <div className="p-6 pt-1 flex justify-between items-center mt-auto border-t border-subtle/40 relative z-10">
            <button
              onClick={closeAndComplete}
              className="text-xs font-bold text-muted hover:text-main transition-colors px-3 py-2 cursor-pointer"
            >
              {isHindi ? "छोड़ें" : "Skip"}
            </button>
            <button
              onClick={() => {
                if (currentSlide === slides.length - 1) {
                  closeAndComplete();
                } else {
                  setCurrentSlide(s => s + 1);
                }
              }}
              className="flex items-center gap-1.5 bg-gradient-to-r from-blue-600 to-blue-700 hover:from-blue-700 hover:to-blue-800 text-white px-5 py-2.5 rounded-xl font-black text-xs uppercase tracking-wider shadow-md shadow-blue-500/25 transition-all cursor-pointer"
            >
              {currentSlide === slides.length - 1
                ? (isHindi ? "शुरू करें 🚀" : "Get Started 🚀")
                : (isHindi ? "आगे बढ़ें" : "Next")}
              {currentSlide < slides.length - 1 && <ChevronRight className="w-4 h-4" />}
            </button>
          </div>
        </motion.div>
      </AnimatePresence>
    </div>
  );
}

export default function OnboardingOverlay() {
  return (
    <OnboardingBoundary>
      <OnboardingOverlayInner />
    </OnboardingBoundary>
  );
}
