'use client';

import React from 'react';
import Link from 'next/link';
import { usePathname } from 'next/navigation';
import { Search, Activity, Ticket, Newspaper, ShieldAlert } from 'lucide-react';
import { motion, AnimatePresence } from 'framer-motion';

export default function BottomNav() {
  const pathname = usePathname();

  const navItems = [
    { label: 'Search',     href: '/',         icon: Search     },
    { label: 'Live',       href: '/live',      icon: Activity   },
    { label: 'PNR',        href: '/pnr',       icon: Ticket     },
    { label: 'News',       href: '/news',      icon: Newspaper  },
    { label: 'Complaint', href: '/complaint',  icon: ShieldAlert },
  ];

  return (
    <div className="md:hidden fixed bottom-0 left-0 right-0 z-40 bg-card/95 dark:bg-[#0c121e]/95 backdrop-blur-md border-t border-strong px-1 py-1.5 safe-bottom shadow-[0_-4px_20px_rgba(0,0,0,0.12)] dark:shadow-[0_-4px_25px_rgba(0,0,0,0.5)]">
      <div className="flex items-center justify-around h-14">
        {navItems.map((item) => {
          const Icon = item.icon;
          const isActive = item.href === '/'
            ? pathname === '/'
            : pathname.startsWith(item.href);

          return (
            <Link
              key={item.href}
              href={item.href}
              className="relative flex flex-col items-center justify-center flex-1 py-1.5 px-1 rounded-xl touch-manipulation select-none group"
            >
              {/* Animated active pill background */}
              <AnimatePresence>
                {isActive && (
                  <motion.div
                    layoutId="active-nav-indicator"
                    className="absolute inset-0 bg-primary/12 dark:bg-primary/18 rounded-xl -z-10"
                    initial={{ opacity: 0, scale: 0.8 }}
                    animate={{ opacity: 1, scale: 1 }}
                    exit={{ opacity: 0, scale: 0.8 }}
                    transition={{ type: 'spring', stiffness: 400, damping: 30 }}
                  />
                )}
              </AnimatePresence>

              {/* Icon + label wrapper */}
              <motion.div
                animate={{
                  scale: isActive ? 1.08 : 1,
                  y: isActive ? -1 : 0,
                }}
                transition={{ type: 'spring', stiffness: 350, damping: 22 }}
                className="flex flex-col items-center justify-center gap-1 w-full h-full"
              >
                {/* Icon with glow on active */}
                <motion.div
                  animate={{ color: isActive ? 'var(--brand-primary)' : undefined }}
                  className={isActive ? 'text-primary' : 'text-muted group-hover:text-main transition-colors duration-200'}
                >
                  <Icon className="w-5 h-5" strokeWidth={isActive ? 2.4 : 1.8} />
                </motion.div>

                {/* Label */}
                <motion.span
                  animate={{
                    opacity: isActive ? 1 : 0.6,
                    fontWeight: isActive ? 700 : 500,
                  }}
                  transition={{ duration: 0.18 }}
                  className={`text-[9px] tracking-tight leading-none ${
                    isActive
                      ? 'text-primary'
                      : 'text-muted group-hover:text-main'
                  }`}
                >
                  {item.label}
                </motion.span>
              </motion.div>

              {/* Active dot indicator */}
              <AnimatePresence>
                {isActive && (
                  <motion.div
                    initial={{ opacity: 0, scaleX: 0 }}
                    animate={{ opacity: 1, scaleX: 1 }}
                    exit={{ opacity: 0, scaleX: 0 }}
                    transition={{ duration: 0.2, ease: 'easeOut' }}
                    className="absolute bottom-0.5 left-1/2 -translate-x-1/2 w-4 h-0.5 rounded-full bg-primary"
                  />
                )}
              </AnimatePresence>
            </Link>
          );
        })}
      </div>
    </div>
  );
}
