'use client';

import { useEffect } from 'react';
import { useCapacitor } from '../hooks/useCapacitor';

/**
 * ServiceWorkerRegistrar
 *
 * Mounts in the App Router root layout to register the service worker.
 * To avoid duplicate service worker registrations and update loops,
 * it checks if a root service worker is already registered (e.g., by OneSignal)
 * before registering manually.
 */
export default function ServiceWorkerRegistrar() {
  const { isNative, platform } = useCapacitor();
  useEffect(() => {
    // Guard: only run in browser context
    if (typeof window === 'undefined') return;

    // Guard: browser must support service workers
    if (!('serviceWorker' in navigator)) {
      console.warn('[SW] Service Worker not supported in this browser.');
      return;
    }

    // Guard: in development or localhost, unregister all service workers and clear caches
    const isLocalhost =
      window.location.hostname === 'localhost' ||
      window.location.hostname === '127.0.0.1';

    if (process.env.NODE_ENV === 'development' || isLocalhost) {
      navigator.serviceWorker.getRegistrations().then((registrations) => {
        for (const reg of registrations) {
          reg.unregister().then(() => {
            console.log('[SW] Unregistered development service worker:', reg.scope);
          });
        }
      });
      if ('caches' in window) {
        caches.keys().then((keys) => {
          for (const key of keys) {
            if (/workbox|trayago|next/i.test(key)) {
              caches.delete(key);
            }
          }
        });
      }
      return;
    }

    // Guard: only register over HTTPS in production
    const isSecure = window.location.protocol === 'https:';

    if (!isSecure) {
      console.warn('[SW] Service Worker requires HTTPS. Skipping registration.');
      return;
    }

    const registerSW = () => {
      console.log('[SW] Registering PWA service worker manually...');
      navigator.serviceWorker
        .register('/sw.js')
        .then((registration) => {
          console.log('[SW] PWA manual registration successful. Scope:', registration.scope);
        })
        .catch((err) => {
          console.error('[SW] PWA manual registration failed:', err);
        });
    };

    registerSW();
  }, []);

  // This component renders nothing — it is a side-effect-only hook carrier
  return null;
}

