import { useState, useEffect, useCallback } from 'react';
import axios from 'axios';
import { getToken } from 'firebase/messaging';
import { messaging, firebaseConfig, vapidKey, isValidVapidKey } from '../lib/firebase';
import { API_HOST } from '../lib/api';

export function useFcmToken() {
  const [token, setToken] = useState<string | null>(null);
  const [permission, setPermission] = useState<NotificationPermission>('default');
  const [isLoading, setIsLoading] = useState(false);
  const [isRegistered, setIsRegistered] = useState(false);
  const [error, setError] = useState<string | null>(null);

  // Sync state with current permission on client side
  useEffect(() => {
    if (typeof window !== 'undefined' && 'Notification' in window) {
      setPermission(Notification.permission);
    }
  }, []);

  const registerTokenWithBackend = useCallback(async (fcmToken: string) => {
    try {
      const deviceId = localStorage.getItem('deviceId') || 'web_dev_' + Math.random().toString(36).substring(2);
      
      const payload = {
        device_id: deviceId,
        fcm_token: fcmToken,
        device_type: 'web'
      };

      console.log('[FCM_HOOK] Registering token with backend...', payload);
      await axios.post(`${API_HOST}/api/notifications/register`, payload, {
        headers: {
          'Content-Type': 'application/json'
        }
      });

      console.log('[FCM_HOOK] Token registered successfully.');
      setIsRegistered(true);
      localStorage.setItem('fcm_registered_token', fcmToken);
    } catch (err: any) {
      console.error('[FCM_HOOK] Backend token registration failed:', err.response?.data || err.message);
      setError(err.response?.data?.error || err.message);
    }
  }, []);

  const fetchAndRegisterToken = useCallback(async () => {
    if (!messaging) {
      console.warn('[FCM_HOOK] Messaging instance is null. Skipping token fetch.');
      return null;
    }

    if (!isValidVapidKey(vapidKey)) {
      console.warn('[FCM_HOOK] VAPID key is missing or invalid. Skipping FCM token fetch.');
      return null;
    }


    setIsLoading(true);
    setError(null);

    try {
      // Register custom-scoped service worker for Firebase to avoid OneSignal/default PWA SW collisions
      const swUrl = `/firebase-messaging-sw.js?apiKey=${encodeURIComponent(firebaseConfig.apiKey)}&messagingSenderId=${encodeURIComponent(firebaseConfig.messagingSenderId)}&appId=${encodeURIComponent(firebaseConfig.appId)}&projectId=${encodeURIComponent(firebaseConfig.projectId)}`;
      
      console.log('[FCM_HOOK] Registering FCM service worker...');
      const registration = await navigator.serviceWorker.register(swUrl, {
        scope: '/firebase-cloud-messaging-push-scope'
      });

      console.log('[FCM_HOOK] FCM Service worker registered in scope:', registration.scope);

      // Fetch FCM Token from Firebase
      const fcmToken = await getToken(messaging, {
        vapidKey: vapidKey,
        serviceWorkerRegistration: registration
      });

      if (fcmToken) {
        setToken(fcmToken);
        const cachedToken = localStorage.getItem('fcm_registered_token');

        if (fcmToken !== cachedToken) {
          await registerTokenWithBackend(fcmToken);
        } else {
          console.log('[FCM_HOOK] FCM token unchanged from cache. Skipping registration.');
          setIsRegistered(true);
        }
        setIsLoading(false);
        return fcmToken;
      } else {
        throw new Error('FCM token retrieval returned empty.');
      }
    } catch (err: any) {
      console.error('[FCM_HOOK] Failed to generate or save FCM token:', err);
      setError(err.message || 'Token acquisition failed.');
      setIsLoading(false);
      return null;
    }
  }, [registerTokenWithBackend]);

  const requestPermission = useCallback(async () => {
    if (typeof window === 'undefined' || !('Notification' in window)) {
      setError('Notifications not supported in this browser.');
      return false;
    }

    setIsLoading(true);
    setError(null);

    try {
      console.log('[FCM_HOOK] Requesting browser notification permission...');
      const result = await Notification.requestPermission();
      setPermission(result);
      setIsLoading(false);

      if (result === 'granted') {
        console.log('[FCM_HOOK] Browser permission granted.');
        await fetchAndRegisterToken();
        return true;
      } else {
        console.warn('[FCM_HOOK] Browser notification permission denied:', result);
        return false;
      }
    } catch (err: any) {
      console.error('[FCM_HOOK] Error requesting permission:', err);
      setError(err.message || 'Permission request failed.');
      setIsLoading(false);
      return false;
    }
  }, [fetchAndRegisterToken]);

  // Auto-fetch token on load if permission is already granted
  useEffect(() => {
    if (typeof window !== 'undefined' && 'Notification' in window) {
      if (Notification.permission === 'granted' && messaging) {
        fetchAndRegisterToken();
      }
    }
  }, [fetchAndRegisterToken]);

  return {
    token,
    permission,
    isLoading,
    isRegistered,
    error,
    requestPermission
  };
}
